component extends="testbox.system.BaseSpec" {

	function beforeAll(){
	  SUT = createObject( 'Etl' );
	}

	function run(){

		describe( "My Etl class", function(){			

			it( 'single letter', function(){
				expect( SUT.transform( legacy={"1":["A"]} ) ).toBe( {"a":1} );
			});

			it( 'single score with multiple letters', function(){
				expect( SUT.transform( legacy={"1":["A", "E", "I", "O", "U"]} ) ).toBe( {"a":1,
																						 "e":1,
																						 "i":1,
																						 "o":1,
																						 "u":1} );
			});

			it( 'multiple scores with multiple letters', function(){
				expect( SUT.transform(
					legacy={"1":["A", "E"],
							"2":["D", "G"]} ) ).toBe( {"a":1,"d":2,"e":1,"g":2} );
			});

			it( 'multiple scores with differing numbers of letters', function(){
